# Paste into Azure portal > VM > Run command > RunShellScript. Runs as root.
# ENTRY-SIZED EQUITY FIX (mistake #14). A position's dollar risk is set when it OPENS and
# does not grow with profits other trades bank while it is open - which is what the bot
# physically does. blend_paper.py credited R as a fraction of equity at CLOSE, so paper
# equity overstated what a real account would show. Two lines; all four books share the
# cycle() that holds them, so one fix covers main, tight, sized and short-boost.
#
# Positions already open on the VM carry no risk_usd and fall back to the OLD behaviour
# for their one closing trade, with a log line saying so. Nothing crashes, nothing is lost.
#
# The R record in logs/trades_blend*.csv is untouched and stays comparable across the fix.
# No backslashes on purpose: Run command JSON-decodes the script and would corrupt them.
set -e
APP=/opt/forexbot
cd $APP
STAMP=$(date -u +%Y%m%d-%H%M%S)
cp blend_paper.py logs/blend_paper.py.bak-$STAMP
echo "backup: logs/blend_paper.py.bak-$STAMP"
for f in logs/blend_state.json logs/blend_state_tight.json logs/blend_state_sized.json logs/blend_state_sboost.json; do
  test -f $f && cp $f $f.bak-$STAMP || true
done
echo "state files backed up too - equity is in there"
echo '' | base64 -d | gunzip > blend_paper.py.new
echo "15c8d624027e7018383edb3eb6b7ff32be5e813773d5c95c0e22728a4a32a363  blend_paper.py.new" | sha256sum -c -
./.venv/bin/python -c "import ast; ast.parse(open('blend_paper.py.new').read()); print('syntax ok')"
grep -c 'risk_usd' blend_paper.py.new
echo "^ must be 3: one at open, one stored, one read at close"
OWNER=$(stat -c %U blend_paper.py)
mv blend_paper.py.new blend_paper.py
chown $OWNER:$OWNER blend_paper.py
echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | ENTRY-SIZED EQUITY FIX APPLIED (mistake #14). Equity before this line was credited on equity-at-close and is overstated; R is unaffected." >> logs/blend_paper.log
systemctl restart blend-paper
echo "restarted; waiting 150s for a full cycle"
sleep 150
systemctl is-active blend-paper
journalctl -u blend-paper -n 80 --no-pager | grep -E 'error|Traceback|pre-fix' || true
sudo -u $OWNER ./.venv/bin/python blend_paper.py --status | tail -26
